/*
 * A387356  Numbers whose set of cyclic permutations has GCD = 1.
 * https://oeis.org/A387356
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n-th positive integer whose set of cyclic
 *            permutations has GCD equal to 1. The sequence is generated by
 *            testing each integer in order and counting the ones that satisfy
 *            the condition
 * Range:     u8 n <= 46, u16 n <= 7399, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   digit_len, gcd, pow_uint
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/gcd.h"
#include "../utils/pow_uint.h"
#include "../utils/digit_len.h"

seq_t a(idx_t n)
{
    seq_t candidate = (seq_t)1;
    idx_t count = 0;

    while (1) {
        /*----- test whether candidate satisfies the definition -----*/
        int k = digit_len(candidate);          /* number of decimal digits */
        seq_t pow10 = pow_uint(10, (idx_t)(k - 1));

        seq_t rot = candidate;
        seq_t g = 0;                          /* running GCD of rotations */

        for (int i = 0; i < k; i++) {
            g = (g == 0) ? rot : gcd(g, rot);

            if (i + 1 < k) {                 /* compute next rotation */
                seq_t first = rot / pow10;
                seq_t rem   = rot % pow10;
                rot = rem * (seq_t)10 + first;
            }
        }

        if (g == (seq_t)1) {                 /* qualifies */
            count++;
            if (count == n)
                return candidate;
        }

        candidate = candidate + (seq_t)1;     /* next integer to test */
    }
}
